<template><div class="scan-page" v-loading="loading"><header><div class="brand">万悦城</div><div>施工现场巡检</div></header><el-result v-if="error" icon="error" title="许可证无效" :sub-title="error"/><template v-else-if="row"><el-card shadow="never"><div class="permit-head"><div><small>施工许可证</small><h2>{{ row.permitNo }}</h2></div><el-tag :type="valid?'success':'danger'" size="large">{{ valid?'有效':'已失效' }}</el-tag></div><el-descriptions :column="1" border><el-descriptions-item label="施工位置">{{ location }}</el-descriptions-item><el-descriptions-item label="施工类型">{{ typeLabel(row.workflowType) }}</el-descriptions-item><el-descriptions-item label="施工周期">{{ formatDateTime(row.constructionStartTime) }} 至 {{ formatDateTime(row.constructionEndTime) }}</el-descriptions-item><el-descriptions-item label="商户">{{ row.merchantName }}</el-descriptions-item><el-descriptions-item label="施工负责人">{{ row.constructionPrincipalName }} {{ row.constructionPrincipalPhone }}</el-descriptions-item><el-descriptions-item label="当前状态">{{ statusLabel(row.status) }}</el-descriptions-item></el-descriptions></el-card>
<el-card shadow="never"><template #header>现场巡检</template><template v-if="!userStore.token"><el-alert title="查看许可证无需登录；提交巡检需要登录系统以登记巡检人员。" type="info" :closable="false"/><el-button class="full" type="primary" @click="login">登录后巡检</el-button></template><template v-else-if="inspectionOptions.length"><el-form label-position="top"><el-form-item label="巡检类型"><el-select v-model="form.type" style="width:100%" @change="resetAnswers"><el-option v-for="item in inspectionOptions" :key="item.value" :label="item.label" :value="item.value"/></el-select></el-form-item>
<div v-if="currentTemplate" class="questions"><div v-for="(field,index) in currentFields" :key="field.key" class="question"><div class="question-label"><span>{{ index+1 }}. {{ field.label }}</span><em v-if="field.required">必填</em></div><el-radio-group v-if="field.controlType==='NORMAL_ABNORMAL'" v-model="answers[field.key]"><el-radio value="NORMAL">正常</el-radio><el-radio value="ABNORMAL">异常</el-radio></el-radio-group><el-radio-group v-else-if="field.controlType==='BOOLEAN'" v-model="answers[field.key]"><el-radio :value="true">是</el-radio><el-radio :value="false">否</el-radio></el-radio-group><el-select v-else-if="field.controlType==='SELECT'" v-model="answers[field.key]" style="width:100%"><el-option v-for="o in field.options" :key="o" :label="o" :value="o"/></el-select><el-checkbox-group v-else-if="field.controlType==='MULTISELECT'" v-model="answers[field.key]"><el-checkbox v-for="o in field.options" :key="o" :value="o">{{ o }}</el-checkbox></el-checkbox-group><el-input-number v-else-if="field.controlType==='NUMBER'" v-model="answers[field.key]" style="width:100%"/><el-input v-else v-model="answers[field.key]" type="textarea" :rows="2"/></div></div>
<el-alert v-if="hasAbnormal" title="存在异常检查项，本次巡检将自动登记为“存在问题”。" type="warning" :closable="false" show-icon/><el-form-item v-if="hasAbnormal" label="问题补充说明"><el-input v-model="form.problemDescription" type="textarea" :rows="3" placeholder="可补充异常位置、现象等信息"/></el-form-item><el-form-item v-if="hasAbnormal" label="整改要求"><el-input v-model="form.rectificationRequirement" type="textarea" :rows="3"/></el-form-item><el-form-item v-if="hasAbnormal" label="整改期限"><el-date-picker v-model="form.rectificationDeadline" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" style="width:100%"/></el-form-item><el-form-item label="现场照片"><input type="file" accept="image/jpeg,image/png" multiple @change="selectFiles"><small class="file-hint">已选择 {{ files.length }} 张；标记要求拍照的检查项出现异常时必须上传。</small></el-form-item><el-progress v-if="submitting" :percentage="uploadProgress"/><el-button class="full" type="primary" :disabled="!valid" :loading="submitting" @click="submitInspection">提交巡检记录</el-button></el-form></template><el-alert v-else title="当前账号没有施工巡检权限，请联系管理员分配。" type="warning" :closable="false"/></el-card>
<el-card shadow="never"><template #header>最近巡检记录</template><el-empty v-if="!row.inspections?.length" description="暂无巡检记录"/><div v-for="item in row.inspections" :key="item.id" class="inspection"><div><strong>{{ inspectionLabel(item.inspectionType) }}</strong><el-tag :type="item.result==='NORMAL'?'success':'danger'" size="small">{{ item.result==='NORMAL'?'正常':'存在问题' }}</el-tag></div><p>{{ item.problemDescription||'无异常' }}</p><ul v-if="answerSummary(item).length" class="answer-list"><li v-for="line in answerSummary(item)" :key="line">{{ line }}</li></ul><small>{{ item.inspectorName }} · {{ formatDateTime(item.inspectedAt) }}</small></div></el-card></template></div></template>
<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { constructionApi, constructionInspectionTemplateApi, type ConstructionWorkflow, type ConstructionInspectionField, type ConstructionInspectionTemplate } from '@/api/construction'
import { useUserStore } from '@/stores/user'
import { formatDateTime } from '@/utils/format'
const route=useRoute(),router=useRouter(),userStore=useUserStore(),row=ref<ConstructionWorkflow>(),templates=ref<ConstructionInspectionTemplate[]>([]),loading=ref(false),error=ref(''),submitting=ref(false),uploadProgress=ref(0)
const form=reactive({type:'',result:'NORMAL',problemDescription:'',rectificationRequirement:'',rectificationDeadline:''}),answers=reactive<Record<string,any>>({}),files=ref<File[]>([])
const location=computed(()=>`${row.value?.floorName||row.value?.floorCode||''} ${row.value?.stallCode||''}`),valid=computed(()=>!!row.value&&['IN_PROGRESS','PENDING_ACCEPTANCE','REJECTED'].includes(row.value.status))
const allOptions=[{value:'security',type:'SECURITY',label:'安保巡检',p:'construction.inspect.security'},{value:'engineering',type:'ENGINEERING',label:'工程巡检',p:'construction.inspect.engineering'},{value:'cleaning',type:'CLEANING',label:'保洁巡检',p:'construction.inspect.cleaning'}]
const inspectionOptions=computed(()=>allOptions.filter(i=>userStore.hasPermission(i.p)&&templates.value.some(t=>t.inspectionType===i.type&&(t.enabled===true||Number(t.enabled)===1))))
const currentTemplate=computed(()=>templates.value.find(t=>t.inspectionType===form.type.toUpperCase()))
const currentFields=computed<ConstructionInspectionField[]>(()=>{try{return (JSON.parse(currentTemplate.value?.fieldsJson||'[]')||[]).filter((f:any)=>f.enabled!==false).sort((a:any,b:any)=>(a.sortOrder||0)-(b.sortOrder||0))}catch{return[]}})
const abnormalFields=computed(()=>currentFields.value.filter(f=>!empty(answers[f.key])&&abnormal(f,answers[f.key]))),hasAbnormal=computed(()=>abnormalFields.value.length>0)
function empty(v:any){return v===undefined||v===null||v===''||(Array.isArray(v)&&!v.length)}
function abnormal(f:ConstructionInspectionField,v:any){if(f.controlType==='NORMAL_ABNORMAL')return v!=='NORMAL';if(f.normalValue===undefined||f.normalValue===null||f.normalValue==='')return false;if(Array.isArray(v))return !v.map(String).includes(String(f.normalValue));return String(v)!==String(f.normalValue)}
function resetAnswers(){Object.keys(answers).forEach(k=>delete answers[k]);currentFields.value.forEach(f=>{if(f.controlType==='MULTISELECT')answers[f.key]=[]});form.problemDescription='';form.rectificationRequirement='';form.rectificationDeadline=''}
function typeLabel(v:string){return v==='MERCHANT_CONSTRUCTION_ENTRY'?'入场装修':'撤场施工'}
function statusLabel(v:string){return({IN_PROGRESS:'施工中',PENDING_ACCEPTANCE:'待验收',REJECTED:'整改中',ARCHIVED:'已归档',CANCELLED:'已取消'}as any)[v]||v}
function inspectionLabel(v:string){return({SECURITY:'安保巡检',ENGINEERING:'工程巡检',CLEANING:'保洁巡检'}as any)[v]||v}
function answerSummary(item:any){try{const fields=JSON.parse(item.templateSnapshotJson||'[]'),values=JSON.parse(item.answersJson||'{}');return fields.filter((f:any)=>f.enabled!==false&&!empty(values[f.key])).map((f:any)=>`${f.label}：${displayAnswer(values[f.key])}`)}catch{return[]}}
function displayAnswer(v:any){if(Array.isArray(v))return v.join('、');if(v===true)return '是';if(v===false)return '否';if(v==='NORMAL')return '正常';if(v==='ABNORMAL')return '异常';return String(v)}
function login(){router.push({path:'/login',query:{redirect:route.fullPath}})}
async function load(){row.value=await constructionApi.publicGet(String(route.params.token)) as any}
function selectFiles(event:Event){files.value=Array.from((event.target as HTMLInputElement).files||[])}
async function submitInspection(){if(!form.type){ElMessage.warning('请选择巡检类型');return}const missing=currentFields.value.find(f=>f.required&&empty(answers[f.key]));if(missing){ElMessage.warning(`请完成必填项：${missing.label}`);return}const needPhoto=abnormalFields.value.some(f=>f.requirePhotoOnAbnormal);if(needPhoto&&!files.value.length){ElMessage.warning('异常检查项要求上传现场照片');return}submitting.value=true;uploadProgress.value=5;try{const payload={...form,result:hasAbnormal.value?'ISSUE':'NORMAL',answersJson:JSON.stringify(answers)};const inspection:any=await constructionApi.inspect(row.value!.id,form.type as any,payload);let done=0;for(const file of files.value){await constructionApi.uploadAttachment(row.value!.id,'INSPECTION',inspection.id,'INSPECTION',file,p=>uploadProgress.value=Math.round((done*100+p)/Math.max(files.value.length,1)));done++}uploadProgress.value=100;ElMessage.success('巡检记录和现场照片已提交');files.value=[];resetAnswers();await load()}finally{submitting.value=false}}
onMounted(async()=>{loading.value=true;try{if(userStore.token){await userStore.fetchMe().catch(()=>userStore.logout());if(userStore.token)templates.value=await constructionInspectionTemplateApi.list(true) as any}await load();form.type=inspectionOptions.value[0]?.value||'';resetAnswers()}catch(e:any){error.value=e?.message||'未找到施工许可证'}finally{loading.value=false}})
</script>
<style scoped>.scan-page{max-width:680px;margin:auto;min-height:100vh;background:#f5f7fa;padding:14px}.scan-page header{display:flex;justify-content:space-between;align-items:center;padding:8px 4px 16px;font-weight:700}.brand{font-size:22px}.el-card+.el-card{margin-top:14px}.permit-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.permit-head small{color:#909399}.permit-head h2{margin:5px 0 0}.full{width:100%;min-height:46px;margin-top:14px}.file-hint{display:block;color:#909399;margin-top:6px}.questions{margin:8px 0 16px}.question{padding:14px 0;border-bottom:1px solid #ebeef5}.question-label{display:flex;gap:8px;margin-bottom:10px;font-weight:600}.question-label em{font-style:normal;color:#f56c6c;font-size:12px}.inspection{padding:12px 0;border-bottom:1px solid #ebeef5}.inspection>div{display:flex;justify-content:space-between}.inspection p{color:#606266;margin:8px 0}.inspection small{color:#909399}.answer-list{margin:6px 0 10px;padding-left:20px;color:#606266;font-size:13px}</style>
